const header=document.querySelector('[data-header]'),triggers=[...document.querySelectorAll('.nav-trigger')],panels=[...document.querySelectorAll('.mega-menu')];function closeMenus(){triggers.forEach(b=>b.setAttribute('aria-expanded','false'));panels.forEach(p=>p.classList.remove('is-open'))}triggers.forEach(button=>button.addEventListener('click',()=>{const wasOpen=button.getAttribute('aria-expanded')==='true';closeMenus();if(!wasOpen){button.setAttribute('aria-expanded','true');document.querySelector(`[data-panel="${button.dataset.menu}"]`).classList.add('is-open')}}));document.addEventListener('click',e=>{if(!header.contains(e.target))closeMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenus()});
const toggle=document.querySelector('.menu-toggle'),drawer=document.querySelector('.mobile-drawer');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));toggle.innerHTML=`<i class="fa-solid fa-${open?'bars':'xmark'}"></i>`;drawer.hidden=open});drawer.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{drawer.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<i class="fa-solid fa-bars"></i>'}));
const quotes=[...document.querySelectorAll('.quote-stage blockquote')];let quoteIndex=0;const current=document.querySelector('[data-current]');function showQuote(next){quotes[quoteIndex].classList.remove('is-active');quoteIndex=(next+quotes.length)%quotes.length;quotes[quoteIndex].classList.add('is-active');current.textContent=quoteIndex+1}document.querySelector('[data-next]').addEventListener('click',()=>showQuote(quoteIndex+1));document.querySelector('[data-prev]').addEventListener('click',()=>showQuote(quoteIndex-1));
const criteria=document.querySelector('[data-criteria]'),summary=document.querySelector('[data-summary]'),briefLink=document.querySelector('[data-brief-link]');function updateBrief(){const data=new FormData(criteria),phrase=`${data.get('outcome')} for ${String(data.get('audience')).toLowerCase()}`;summary.textContent=phrase;briefLink.href=`mailto:info@abacusdesk.com?subject=${encodeURIComponent('Abacus Desk enquiry: '+data.get('outcome'))}&body=${encodeURIComponent('Our starting brief: '+phrase+'.\n\nPlease contact me to discuss the next step.')}`}criteria.addEventListener('change',updateBrief);updateBrief();
const revealTargets=document.querySelectorAll('.section h2,.section .lead,.section article,.project,.intro-columns p,.cap-grid>*,.client-names span');revealTargets.forEach(el=>el.classList.add('reveal'));if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in');observer.unobserve(entry.target)}}),{threshold:.12});revealTargets.forEach(el=>observer.observe(el))}else revealTargets.forEach(el=>el.classList.add('in'));
const strip=document.querySelector('.work-strip');let down=false,startX=0,startScroll=0;strip.addEventListener('pointerdown',e=>{down=true;startX=e.clientX;startScroll=strip.scrollLeft;strip.setPointerCapture(e.pointerId)});strip.addEventListener('pointermove',e=>{if(down)strip.scrollLeft=startScroll-(e.clientX-startX)});strip.addEventListener('pointerup',()=>down=false);strip.addEventListener('pointercancel',()=>down=false);
